INSERT INTO public.resources(title,description,type,category,url,duration,level,status,provider,requirements,materials,tags,order_index,is_active,metadata)
SELECT r.title,r.description,r.type,r.category,r.url,r.duration,r.level,r.status,r.provider,r.requirements,r.materials,r.tags,r.order_index,true,'{"curated_source":"official-docs-2026-11-08"}'::jsonb
FROM jsonb_populate_record(NULL::public.resources,'{"title":"Web development foundations","description":"Start with HTML, CSS and JavaScript, then explore responsive design, performance and privacy. Follow a course from start to finish or jump to the topic you need for your next project.","type":"documentation","category":"Web Development","url":"https://web.dev/learn","duration":"Self-paced","level":"Beginner","status":"Available","provider":"Google · web.dev","requirements":["A browser and a code editor"],"materials":["HTML, CSS and JavaScript courses","Responsive design and performance guides"],"tags":["web","HTML","CSS","JavaScript"],"order_index":10}'::jsonb) r
WHERE NOT EXISTS(SELECT 1 FROM public.resources existing WHERE existing.url=r.url);
